function drawCombatFx(){let now=performance.now();combatFx=combatFx.filter(f=>now-f.born<700);for(let f of combatFx){let age=(now-f.born)/700,[X,Y]=tileXY(f.x,f.y);ctx.globalAlpha=1-age;ctx.fillStyle=f.color;ctx.font=`bold ${Math.max(13,p.tile*.34)}px sans-serif`;ctx.textAlign='center';ctx.strokeStyle='#24130e';ctx.lineWidth=3;ctx.strokeText(f.text,X+p.tile*.5,Y+p.tile*(.25-age*.45));ctx.fillText(f.text,X+p.tile*.5,Y+p.tile*(.25-age*.45));ctx.globalAlpha=1}}
function itemAt(x,y){return objects.concat(drops).some(a=>a.x===x&&a.y===y)}
function occupied(x,y,animal=false){if(x<0||y<0||x>=COLS||y>=ROWS||map[y][x])return true;if(structures.some(a=>a.x===x&&a.y===y&&a.type!=='trap'&&!(a.type==='door'&&!animal)))return true;return !animal&&enemies.some(a=>a.x===x&&a.y===y)}
occupied=function(x,y,animal=false){if(x<0||y<0||x>=COLS||y>=ROWS)return true;let bridge=structures.some(a=>a.x===x&&a.y===y&&a.type==='bridge');if(map[y][x]&&!bridge&&(animal||!inv.boat))return true;if(structures.some(a=>a.x===x&&a.y===y&&!['trap','bridge'].includes(a.type)&&!(a.type==='door'&&!animal)))return true;return !animal&&enemies.some(a=>a.x===x&&a.y===y)};
function pathfind(tx,ty,animal=false,start={x:p.x,y:p.y}){let q=[start],seen=new Map([[`${start.x},${start.y}`,null]]),end;while(q.length){let a=q.shift();if(a.x===tx&&a.y===ty){end=a;break}for(let[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let n={x:a.x+dx,y:a.y+dy},k=`${n.x},${n.y}`;if(!seen.has(k)&&(!occupied(n.x,n.y,animal)||(n.x===tx&&n.y===ty))){seen.set(k,a);q.push(n)}}}if(!end)return null;let out=[];while(end.x!==start.x||end.y!==start.y){out.unshift(end);end=seen.get(`${end.x},${end.y}`)}return out}
function nextTo(x,y){let best=[[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dy])=>({x:x+dx,y:y+dy})).filter(a=>!occupied(a.x,a.y)).map(a=>({a,path:pathfind(a.x,a.y)})).filter(a=>a.path).sort((a,b)=>a.path.length-b.path.length)[0];if(best)p.path=best.path;else if(aiOn)logEvent(`AI跳过无法到达的目标 ${x},${y}`,'ai');else toast('无法靠近目标')}
function tap(e){if(!started||p.health<=0)return;let r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left-p.ox)/p.tile+cameraX),y=Math.floor((e.clientY-r.top-p.oy)/p.tile);if(x<0||y<0||x>=COLS||y>=ROWS)return;selected={x,y};showDismantle(null);if(['trap','fence','door','kitchen','fridge','bed','shelter','strongShelter'].includes(mode)){place(x,y);return}let foe=enemies.find(a=>a.x===x&&a.y===y);if(foe){Math.abs(p.x-x)+Math.abs(p.y-y)===1?attack(foe):nextTo(x,y);return}let item=objects.concat(drops).find(a=>a.x===x&&a.y===y);if(item){Math.abs(p.x-x)+Math.abs(p.y-y)===1?pickupPrompt(item):nextTo(x,y);return}let build=structures.find(a=>a.x===x&&a.y===y);if(build&&Math.abs(p.x-x)+Math.abs(p.y-y)===1){if(build.type==='kitchen')kitchenPrompt(build);else if(build.type==='bed')bedPrompt(build);else if(['fence','door'].includes(build.type))fencePrompt(build);else buildingPrompt(build);return}hideAction();if(map[y][x]){if(inv.rod&&Math.abs(p.x-x)+Math.abs(p.y-y)===1)fish();else toast(inv.rod?'请先站到岸边':'水里不能走，需要鱼竿');return}let path=pathfind(x,y);if(path)p.path=path;else toast('那里过不去')}
function pickupPrompt(a){let g=growthInfo(a),growing=['wood','grass'].includes(a.type);$('#actionIcon').textContent=g.icon;$('#actionTitle').textContent=`采集${g.name}`;$('#actionText').textContent=a.type==='carcass'?'必须在厨房烹饪':growing?(g.next?`现在获得 ${g.yield} 份；继续生长会增产`:`已经成熟，可获得 ${g.yield} 份`):'收入背包';$('#actionButton').textContent='采集';$('#actionButton').disabled=false;$('#actionButton').onclick=()=>pickup(a);$('#actionPrompt').classList.remove('hidden')}
function pickup(a){let pool=objects.includes(a)?objects:drops,g=growthInfo(a),bonus=['wood','grass'].includes(a.type)?Math.floor(worldEra()/2)+(worldProfile.yieldBonus||0)+(dailyEvent==='丰收'?2:0):0,total=g.yield+bonus;pool.splice(pool.indexOf(a),1);inv[a.type]+=total;toast(`采集 ${g.icon} ${g.name}，获得${defs[a.type][0]} ×${total}${bonus?`（世界进程 +${bonus}）`:''}`);hideAction();updateUI();save()}
function kitchenPrompt(build){let n=inv.fish+inv.carcass;$('#actionIcon').textContent='♨';$('#actionTitle').textContent='野外厨房';$('#actionText').textContent=n?`可烹饪 ${n} 份食材`:'没有生鱼或动物肉';$('#actionButton').textContent='烹饪';$('#actionButton').disabled=!n;$('#actionButton').onclick=cook;showDismantle(build);$('#actionPrompt').classList.remove('hidden')}
function cook(){let n=inv.fish+inv.carcass;if(!n)return;inv.meal+=n;inv.fish=inv.carcass=0;toast(`得到熟食 ×${n}`);kitchenPrompt();updateUI();save()}
function bedPrompt(build){$('#actionIcon').textContent='🛏️';$('#actionTitle').textContent='木床';$('#actionText').textContent=p.health>=100?'健康已经全满':'睡觉恢复 30 点健康';$('#actionButton').textContent='睡觉';$('#actionButton').disabled=p.health>=100;$('#actionButton').onclick=sleep;showDismantle(build);$('#actionPrompt').classList.remove('hidden')}
function sleep(){p.health=Math.min(100,p.health+30);p.hunger=Math.max(0,p.hunger-8);toast('休息完成：健康 +30，饥饿 -8');hideAction();save()}
function wallName(wall,level=wall.level||1){let names=wall.type==='door'?['简易木门','加固木门','强化木门']:['简易木栏','加固木栏','强化护栏'];return names[level-1]}
function fencePrompt(wall){let level=wall.level||1,cost={wood:level+2,grass:1},can=level<3&&inv.wood>=cost.wood&&inv.grass>=cost.grass;$('#actionIcon').textContent=wall.type==='door'?'▯':'▥';$('#actionTitle').textContent=`${wallName(wall)} · ${level}级`;$('#actionText').textContent=level>=3?`最高等级 · 耐久 ${Math.ceil(wall.hp)}/${wall.maxHp}`:`点击升级后直接替换为${wallName(wall,level+1)} · 需要木头 ${cost.wood}、草 1 · 当前耐久 ${Math.ceil(wall.hp)}/${wall.maxHp}`;$('#actionButton').textContent=level>=3?'已满级':'升级替换';$('#actionButton').disabled=!can;$('#actionButton').onclick=()=>upgradeWall(wall);showDismantle(wall);$('#actionPrompt').classList.remove('hidden')}
function upgradeWall(wall){let level=wall.level||1;if(level>=3)return;let wood=level+2;if(inv.wood<wood||inv.grass<1)return;inv.wood-=wood;inv.grass--;wall.level=level+1;wall.maxHp=[80,200,400][level];wall.hp=wall.maxHp;toast(`已替换为${wallName(wall)}，房屋防护 ${wall.level}，耐久 ${wall.maxHp}`);hideAction();updateUI();save()}
function spoilRawFood(){if(structures.some(a=>a.type==='fridge'))return;let lost=0;for(let type of ['fish','carcass'])if(inv[type]>0){inv[type]--;lost++}if(lost)toast(`没有木冰箱，${lost} 份生鲜腐坏了`)}
function showDismantle(build){let b=$('#dismantleButton');b.classList.toggle('hidden',!build);if(build)b.onclick=()=>dismantle(build)}
function buildingPrompt(build){$('#actionIcon').textContent=defs[build.type]?.[1]||'⌂';$('#actionTitle').textContent=defs[build.type]?.[0]||'建筑';$('#actionText').textContent='可以拆除后重新规划或扩建';$('#actionButton').textContent='保留';$('#actionButton').disabled=false;$('#actionButton').onclick=hideAction;showDismantle(build);$('#actionPrompt').classList.remove('hidden')}
const normalBuildingPrompt=buildingPrompt;
buildingPrompt=function(build){if(build.type!=='bridge')return normalBuildingPrompt(build);let missing=Math.max(0,(build.maxHp||100)-build.hp),cost=Math.max(1,Math.ceil(missing/25)),can=missing>0&&inv.wood>=cost;$('#actionIcon').textContent='🌉';$('#actionTitle').textContent='木桥维护';$('#actionText').textContent=missing?`耐久 ${Math.ceil(build.hp)}/${build.maxHp} · 使用木头 ${cost} 完全修复`:'耐久完好；涨潮期间会逐渐损耗';$('#actionButton').textContent=missing?'维修':'无需维修';$('#actionButton').disabled=!can;$('#actionButton').onclick=()=>{inv.wood-=cost;build.hp=build.maxHp;toast('木桥已经修复');hideAction();updateUI();save()};showDismantle(build);$('#actionPrompt').classList.remove('hidden')};
function dismantle(build){let i=structures.indexOf(build);if(i<0)return;structures.splice(i,1);let recipe=recipes.find(r=>r.id===build.type);if(recipe)for(let[k,n]of Object.entries(recipe.cost))if(defs[k]&&!['spear','strongSpear'].includes(k))inv[k]+=Math.floor(n/2);toast(`拆除${defs[build.type]?.[0]||'建筑'}，返还部分材料`);hideAction();updateUI();save()}
function hideAction(){$('#actionPrompt').classList.add('hidden');showDismantle(null)}
function fish(){toast('抛下鱼线…');setTimeout(()=>{inv.fish++;toast('钓到生鱼，请带到厨房');updateUI()},1000)}
function weaponInfo(){if(inv.hunterSpear)return{name:'猎兽矛',icon:'⚔️',damage:95};if(inv.strongSpear)return{name:'加固长矛',icon:'🔱',damage:65};if(inv.spear)return{name:'木矛',icon:'🗡️',damage:40};return{name:'徒手',icon:'✊',damage:15}}
function attack(e){let animal=ANIMALS[e.kind]||ANIMALS.boar,weapon=weaponInfo();playerAttackUntil=performance.now()+260;playerAttackTarget={x:e.x,y:e.y};e.hp-=weapon.damage;e.hit=true;addCombatFx(e.x,e.y,`-${weapon.damage}`,'#ffe07b');setTimeout(()=>e.hit=false,180);toast(`${weapon.name}攻击${animal.name}，伤害 ${weapon.damage}`);if(e.hp<=0){runStats.kills++;enemies.splice(enemies.indexOf(e),1);drops.push({x:e.x,y:e.y,type:'carcass',amount:animal.meat});toast(`击败${animal.name}，掉落生肉 ×${animal.meat}`)}}
function place(x,y){if(!inv[mode])return setMode('hand');let tidal=TIDAL_CELLS.some(a=>a.x===x&&a.y===y),bridge=structures.find(a=>a.x===x&&a.y===y&&a.type==='bridge'),blocked=structures.some(a=>a.x===x&&a.y===y&&a.type!=='bridge');if(tidal&&!bridge)return toast('洪泛浅滩必须先铺木桥，建筑才能以桥面为地基');if(occupied(x,y)||itemAt(x,y)||blocked||p.x===x&&p.y===y)return toast('这里不能建造');let durability={trap:1,fence:80,door:80,kitchen:60,fridge:50,bed:45,shelter:80,strongShelter:160}[mode]||40,building={x,y,type:mode,hp:durability,maxHp:durability,bridgeFoundation:!!bridge};if(['fence','door'].includes(mode))building.level=1;structures.push(building);inv[mode]--;let protection=houseProtection();toast(protection?`房屋已封闭！抵挡动物，天气防护 ${protection}`:`已放置${defs[mode][0]}${bridge?'（桥面地基）':''}`);setMode('hand');updateUI();save()}
function houseInterior(x,y){if(map[y]?.[x])return false;let q=[{x,y}],seen=new Set([`${x},${y}`]),walls=0;while(q.length){let a=q.shift();for(let[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let nx=a.x+dx,ny=a.y+dy;if(nx<0||ny<0||nx>=COLS||ny>=ROWS||map[ny][nx])return false;if(structures.some(s=>s.x===nx&&s.y===ny&&['fence','door'].includes(s.type))){walls++;continue}let k=`${nx},${ny}`;if(!seen.has(k)){seen.add(k);q.push({x:nx,y:ny});if(seen.size>40)return false}}}return walls>=4&&structures.some(s=>s.type==='door')}
function spawnEnemy(){let season=seasonInfo(),spots=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++)if(!occupied(x,y,true)&&!itemAt(x,y)&&!houseInterior(x,y)&&Math.abs(x-p.x)+Math.abs(y-p.y)>5)spots.push({x,y});let maxEnemies=Math.min(9,3+worldEra()+Math.floor(day/5));if(!spots.length||enemies.length>=maxEnemies||Math.random()>Math.min(1,worldProfile.enemy+(dailyEvent==='兽潮'?.25:0)))return;let pool=Object.entries(ANIMALS).filter(([,a])=>day>=a.unlock&&a.seasons.includes(season.name)).sort((a,b)=>a[1].tier-b[1].tier);if(!pool.length)return;let chosen=Math.random()<Math.min(.85,.55+worldEra()*.05)?pool[pool.length-1]:pool[Math.floor(Math.random()*pool.length)],kind=chosen[0],animal=chosen[1],spot=spots[Math.floor(Math.random()*spots.length)],hp=Math.round((animal.hp+Math.floor((day-animal.unlock)/7)*12)*worldProfile.enemy);enemies.push({...spot,kind,hp,maxHp:hp,lastMove:time,lastAttack:0,hit:false});toast(`${animal.tier>=4?'🚨':'⚠'} ${animal.rank}·${animal.name}出现！${hp} 生命 / 攻击 ${animal.damage}`)}
function spawnResources(count=1){const MAX=20+worldEra()*2,season=seasonInfo(),rates=season.resources;if(objects.length>=MAX||Math.random()>Math.min(1,worldProfile.resource+(dailyEvent==='丰收'?.2:0)))return 0;let empty=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++)if(!map[y][x]&&!occupied(x,y)&&!itemAt(x,y)&&!houseInterior(x,y)&&!(p.x===x&&p.y===y))empty.push({x,y});let added=0;while(count--&&empty.length&&objects.length<MAX){let i=Math.floor(Math.random()*empty.length),spot=empty.splice(i,1)[0],roll=Math.random(),type=roll<rates[0]?'wood':roll<rates[0]+rates[1]?'grass':'berry';objects.push({...spot,type,born:time});added++}if(added)save();return added}
function houseProtection(){let q=[{x:p.x,y:p.y}],seen=new Set([`${p.x},${p.y}`]),boundary=[];while(q.length){let a=q.shift();for(let[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let x=a.x+dx,y=a.y+dy;if(x<0||y<0||x>=COLS||y>=ROWS||map[y][x])return 0;let wall=structures.find(s=>s.x===x&&s.y===y&&['fence','door'].includes(s.type));if(wall){boundary.push(wall);continue}let k=`${x},${y}`;if(!seen.has(k)){seen.add(k);q.push({x,y});if(seen.size>40)return 0}}}return boundary.some(s=>s.type==='door')&&boundary.length>=4?Math.min(...boundary.map(s=>s.level||1)):0}
function enclosedByFence(){return houseProtection()>0}
function weatherProtection(){let strength=houseProtection();if(structures.some(a=>a.type==='shelter'&&Math.abs(a.x-p.x)+Math.abs(a.y-p.y)<=1))strength=Math.max(strength,1);if(structures.some(a=>a.type==='strongShelter'&&Math.abs(a.x-p.x)+Math.abs(a.y-p.y)<=1))strength=Math.max(strength,2);return strength}
function enemyAI(){for(let e of [...enemies]){if(time-e.lastMove<750)continue;e.lastMove=time;let animal=ANIMALS[e.kind]||ANIMALS.boar,d=Math.abs(e.x-p.x)+Math.abs(e.y-p.y);if(d===1){if(time-e.lastAttack>1200){let hit=animal.damage+Math.floor((day-animal.unlock)/4)*2;e.lastAttack=time;p.health=Math.max(0,p.health-hit);runStats.damage.enemy+=hit;runStats.lastDamageSource='enemy';toast(`${animal.name}攻击！健康 -${hit}`)}continue}let path=pathfind(p.x,p.y,true,{x:e.x,y:e.y});if(!path?.length){let targets=structures.filter(s=>s.type!=='trap').map(s=>({s,path:pathfind(s.x,s.y,true,{x:e.x,y:e.y})})).filter(a=>a.path?.length).sort((a,b)=>a.path.length-b.path.length),target=targets[0];if(!target)continue;if(target.path.length===1){let building=target.s;building.maxHp=building.maxHp||(['fence','door'].includes(building.type)?40:60);building.hp=(building.hp??building.maxHp)-animal.damage;toast(`${animal.name}攻击${defs[building.type][0]}，耐久 -${animal.damage}`);if(building.hp<=0){structures.splice(structures.indexOf(building),1);toast(`${defs[building.type][0]}被摧毁！`)}continue}path=target.path}let n=path[0];if(n.x===p.x&&n.y===p.y)continue;e.x=n.x;e.y=n.y;let trap=structures.find(a=>a.x===e.x&&a.y===e.y&&a.type==='trap');if(trap){structures.splice(structures.indexOf(trap),1);e.hp-=50;toast(`陷阱命中${animal.name}，生命 -50！`);if(e.hp<=0){runStats.kills++;enemies.splice(enemies.indexOf(e),1);drops.push({x:e.x,y:e.y,type:'carcass',amount:animal.meat});toast(`${animal.name}被陷阱击败，掉落生肉 ×${animal.meat}`)}}}}
function clothingProtection(){let s=seasonInfo().name;if(s==='冬'||['严寒','寒风','降雪'].includes(weather))return inv.warmCoat?1:0;if(s==='夏'||weather==='炎热')return inv.coolClothes?1:0;return 1}
function simulateStep(dt){if(!started||p.health<=0)return;time+=dt;p.hunger=Math.max(0,p.hunger-dt*.00055);if(!p.hunger){let loss=dt*.001;p.health=Math.max(0,p.health-loss);runStats.damage.hunger+=loss;runStats.lastDamageSource='hunger'}let d=Math.floor(time/60000)+1;if(d!==day){let oldSeason=seasonInfo().name;day=d;let season=seasonInfo();weather=season.weather[Math.floor(Math.random()*season.weather.length)][0];let grown=spawnResources(4);toast(`${season.name} · 第 ${day} 天：${weather}，新生物资 ${grown} 份${oldSeason!==season.name?'，新季节开始':''}`)}resourceClock+=dt;while(resourceClock>=8000){resourceClock-=8000;spawnResources(1)}let severity=weatherInfo()[1],weatherDamage=Math.max(0,severity-weatherProtection()),clothingDamage=clothingProtection()?0:1,damage=weatherDamage+clothingDamage;if(damage){weatherClock+=dt;while(weatherClock>=2500){weatherClock-=2500;p.health=Math.max(0,p.health-damage);runStats.damage.weather+=damage;runStats.lastDamageSource='weather';toast(`${weather}与${seasonInfo().name}季环境伤害 ${damage}（建筑防护 ${weatherProtection()}，衣物 ${clothingProtection()?'合适':'不合适'}）`)}}else weatherClock=0;enemyClock+=dt;while(enemyClock>=12000){enemyClock-=12000;if(Math.random()<.75)spawnEnemy()}aiClock+=dt;while(aiOn&&aiClock>=650){aiClock-=650;aiStep()}enemyAI();if(p.path.length){let n=p.path[0],speed=dt*.006,dist=Math.hypot(n.x-p.px,n.y-p.py);if(dist<=speed){p.px=p.x=n.x;p.py=p.y=n.y;p.path.shift()}else{p.px+=(n.x-p.px)/dist*speed;p.py+=(n.y-p.py)/dist*speed}}runStats.minHealth=Math.min(runStats.minHealth,p.health);runStats.minHunger=Math.min(runStats.minHunger,p.hunger);updateStats()}
const baseSimulateStep=simulateStep;
function floodUnprotectedTiles(){let tidal=new Set(TIDAL_CELLS.map(a=>`${a.x},${a.y}`)),bridged=new Set(structures.filter(a=>a.type==='bridge').map(a=>`${a.x},${a.y}`)),lostBuildings=structures.filter(a=>a.type!=='bridge'&&tidal.has(`${a.x},${a.y}`)&&!bridged.has(`${a.x},${a.y}`));for(let a of lostBuildings)structures.splice(structures.indexOf(a),1);let before=objects.length+drops.length;objects=objects.filter(a=>!tidal.has(`${a.x},${a.y}`)||bridged.has(`${a.x},${a.y}`));drops=drops.filter(a=>!tidal.has(`${a.x},${a.y}`)||bridged.has(`${a.x},${a.y}`));let lostItems=before-objects.length-drops.length;if(lostBuildings.length||lostItems)toast(`洪水摧毁：未架桥建筑 ${lostBuildings.length} 座，地面物资 ${lostItems} 份`)}
function damageBridgesForDay(){if(tide!=='涨潮'||lastBridgeDamageDay===day)return;lastBridgeDamageDay=day;let collapsed=[];for(let bridge of structures.filter(a=>a.type==='bridge')){bridge.hp-=15;if(bridge.hp<=0)collapsed.push({x:bridge.x,y:bridge.y})}if(collapsed.length){let keys=new Set(collapsed.map(a=>`${a.x},${a.y}`));structures=structures.filter(a=>!keys.has(`${a.x},${a.y}`));objects=objects.filter(a=>!keys.has(`${a.x},${a.y}`));drops=drops.filter(a=>!keys.has(`${a.x},${a.y}`));toast(`${collapsed.length} 座失修木桥连同桥面建筑和物资被冲垮！`)}else if(structures.some(a=>a.type==='bridge'))toast('涨潮日结算：木桥耐久 -15')}
function updateTide(){let weekDay=(day-1)%7+1,next=weekDay===5||weekDay===6?'涨潮':'退潮';if(next!==tide){tide=next;for(let a of TIDAL_CELLS)map[a.y][a.x]=tide==='涨潮'?1:BASE_TERRAIN[a.y][a.x];p.path=[];if(tide==='涨潮'){floodUnprotectedTiles();toast('🌊 周期涨潮！第5—6天浅滩被淹；无桥建筑和物资会被摧毁')}else toast('🏝 第7天退潮！沿岸浅滩重新露出')}damageBridgesForDay()}
function strandedByTide(){return !!map[p.y]?.[p.x]&&!inv.boat&&!structureAt(p.x,p.y,'bridge')}
simulateStep=function(dt){let previousTime=time,heldAI=aiOn;if(strandedByTide()){p.path=[];aiOn=false}baseSimulateStep(dt);aiOn=heldAI;if(!started)return;updateTide();if(Math.floor(previousTime/12000)!==Math.floor(time/12000))spawnResources(1)};
function animate(now){let elapsed=Math.min(100,now-last);last=now;if(!paused||batchLeft)simAccumulator+=elapsed*(batchLeft?BATCH_SPEED:1);let steps=0;while(simAccumulator>=SIM_STEP&&steps<200){simulateStep(SIM_STEP);simAccumulator-=SIM_STEP;steps++}if(!batchLeft)draw();requestAnimationFrame(animate)}
function rollDailyEvent(){let events=['平静','平静','丰收','兽潮','灾害预警'];dailyEvent=events[Math.floor(Math.random()*events.length)];logEvent(`今日世界事件：${dailyEvent}`,'info')}
function gameSnapshot(){return JSON.parse(JSON.stringify({day,time,weather,dailyEvent,worldProfile,objects,structures,enemies,drops,inv,p:{x:p.x,y:p.y,px:p.x,py:p.y,health:p.health,hunger:p.hunger},runStats}))}
function saveCheckpoint(){if(batchLeft||(day!==1&&(day-1)%3!==0))return;let list=JSON.parse(localStorage.getItem('island-checkpoints-v1')||'[]').filter(s=>s.day!==day);list.push(gameSnapshot());localStorage.setItem('island-checkpoints-v1',JSON.stringify(list.slice(-3)))}
function checkpointCount(){return JSON.parse(localStorage.getItem('island-checkpoints-v1')||'[]').length}
function restoreCheckpoint(){let list=JSON.parse(localStorage.getItem('island-checkpoints-v1')||'[]');if(!list.length)return restartGame();let s=list[list.length-1];objects=s.objects||[];structures=s.structures||[];enemies=s.enemies||[];drops=s.drops||[];inv={...Object.fromEntries(Object.keys(defs).map(k=>[k,0])),...s.inv};worldProfile=s.worldProfile||randomWorldProfile();dailyEvent=s.dailyEvent||'平静';time=s.time;day=lastSpoilDay=s.day;weather=s.weather;p={...p,...s.p,path:[],tile:p.tile,ox:p.ox,oy:p.oy};runStats=s.runStats||{kills:0,meals:0,damage:{enemy:0,weather:0,hunger:0},lastDamageSource:null,minHealth:p.health,minHunger:p.hunger};enemyClock=weatherClock=aiClock=resourceClock=0;runEnding=false;started=true;aiOn=false;localStorage.setItem('island-checkpoints-v1',JSON.stringify([s]));$('#welcome').classList.add('closed');$('#welcome').classList.remove('gameover');$('#restartButton').classList.add('hidden');$('#clearGameButton').classList.add('hidden');updateAIButton();updateUI();save();toast(`已回到第 ${day} 天的安全存档`)}
function updateBatchProgress(force=false){let key=`${batchLeft}-${day}-${evolution?.generation||0}-${evolution?.candidate||0}`;if(!batchLeft||(!force&&lastBatchProgressDay===key))return;lastBatchProgressDay=key;let completed=10-batchLeft,current=completed+1;if(evolution){let overall=(evolution.generation-1)*60+evolution.candidate*10+completed;$('#batchProgressText').textContent=`第 ${evolution.generation} / ${evolution.maxGenerations} 代 · 候选 ${evolution.candidate+1} / ${evolution.population.length} · 本候选第 ${current} / 10 局`;$('#batchProgressBar').style.width=`${overall/3}%`}else{$('#batchProgressText').textContent=`正在模拟第 ${current} / 10 局 · 已完成 ${completed} 局`;$('#batchProgressBar').style.width=`${completed*10}%`}$('#batchProgressDay').textContent=`本局当前存活：${seasonInfo().name} · 第 ${day} 天 · 健康 ${Math.ceil(p.health)}`}
