async function applyRecommendedStrategy(){let button=$('#applyStrategyButton');if(button.dataset.applied)return button.dataset.applied==='evolve'?startEvolution():startTenRuns();if(!LOCAL_AI_LAB||!recommendedStrategy)return;button.disabled=true;$('#strategyStatus').textContent='正在迁移并写入最佳策略…';try{let payload=normalizeStrategy(recommendedStrategy),res=await fetch('/__ai_strategy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await res.json();if(!res.ok)throw new Error(data.error||'写入失败');recommendedStrategy=normalizeStrategy(data.strategy||payload);Object.assign(AI,recommendedStrategy);localStorage.setItem('island-ai-champion',JSON.stringify({avg:Number(JSON.parse(localStorage.getItem('island-ai-champion')||'{}').avg)||0,strategy:{...AI,craftPriority:[...AI.craftPriority]},version:AI.version}));$('#strategyStatus').textContent=`最佳策略 v${data.version} 已写入本地 ai-strategy.js；下一轮会以它作为父代继续变异，而不是重新随机开始。`;button.dataset.applied=recommendationMode==='evolution'?'evolve':'test';button.disabled=false;button.textContent=recommendationMode==='evolution'?`用冠军 v${data.version} 继续进化 300 局`:`用 v${data.version} 继续测试 10 局`}catch(e){$('#strategyStatus').textContent=`无法更新：${e.message}。本地写入需要通过 node server.js 打开游戏。`;button.disabled=false}}
