const GENE_BOUNDS={eatMealBelow:[45,90,5],eatBerryBelow:[25,75,5],fishBelow:[45,95,5],trapThreatDistance:[2,6,1],growthValueWeight:[.5,3,.25],bedHealthBelow:[45,95,5],wallLevel2Day:[2,8,1],wallLevel3Day:[6,16,1],weapon2Day:[2,8,1],weapon3Day:[6,16,1]};
