function crossStrategies(a,b){let out=normalizeStrategy(a);for(let k of Object.keys(GENE_BOUNDS))out[k]=Math.random()<.5?a[k]:b[k];out.buildShelterBeforeBase=Math.random()<.5?a.buildShelterBeforeBase:b.buildShelterBeforeBase;out.craftPriority=(Math.random()<.5?a:b).craftPriority.slice();return mutateStrategy(out,.35)}
function evolutionScore(runs){let days=runs.map(r=>r.day),avg=days.reduce((a,b)=>a+b,0)/days.length,min=Math.min(...days),kills=runs.reduce((n,r)=>n+r.kills,0)/runs.length,meals=runs.reduce((n,r)=>n+r.meals,0)/runs.length,variance=days.reduce((n,d)=>n+(d-avg)**2,0)/days.length;return avg*100+min*25+kills*4+meals*2-Math.sqrt(variance)*12}
