function ensureRealStrategyChange(){let changed=strategyChanges(AI,recommendedStrategy);if(changed.length)return changed;let runs=JSON.parse(localStorage.getItem('island-ai-history')||'[]').slice(0,10),enemy=runs.filter(r=>r.cause==='enemy').length,weatherDeaths=runs.filter(r=>r.cause==='weather').length;if(enemy>=weatherDeaths){recommendedStrategy.weapon2Day=Math.max(2,(AI.weapon2Day||5)-1);recommendedStrategy.wallLevel2Day=Math.max(2,(AI.wallLevel2Day||5)-1);recommendedStrategy.description='陷阱距离已到上限：改为更早升级武器和围栏'}else{recommendedStrategy.wallLevel2Day=Math.max(2,(AI.wallLevel2Day||5)-1);recommendedStrategy.bedHealthBelow=Math.min(95,(AI.bedHealthBelow||75)+5);recommendedStrategy.description='原天气参数已无变化：改为更早升级防线并提前休息'}changed=strategyChanges(AI,recommendedStrategy);if(!changed.length){recommendedStrategy.growthValueWeight=Number(((AI.growthValueWeight||1.5)+.25).toFixed(2));recommendedStrategy.description='原候选没有真实变化：提高成熟资源的采集价值'}return strategyChanges(AI,recommendedStrategy)}
function renderFinalStrategyDiff(){if(!recommendedStrategy)return;let labels={eatMealBelow:'熟食进食阈值',eatBerryBelow:'浆果进食阈值',fishBelow:'开始钓鱼阈值',trapThreatDistance:'陷阱警戒距离',buildShelterBeforeBase:'围墙前先造棚屋',growthValueWeight:'成熟资源价值权重',bedHealthBelow:'上床休息生命阈值',wallLevel2Day:'二级围栏目标日',wallLevel3Day:'三级围栏目标日',weapon2Day:'加固长矛目标日',weapon3Day:'猎兽矛目标日',craftPriority:'制作优先级',testSpeed:'旧测试倍率'},changed=ensureRealStrategyChange(),rows=changed.map(k=>`<tr><td>${labels[k]||k}</td><td>${strategyValue(AI[k])}</td><td class="changed">${strategyValue(recommendedStrategy[k])}</td></tr>`).join('');$('#strategyDiff').innerHTML=`<p><b>本轮实际优化：</b>${recommendedStrategy.description}</p><p>版本 ${AI.version} → ${recommendedStrategy.version}，共改变 <b>${changed.length}</b> 个策略参数。</p><table><thead><tr><th>改变的参数</th><th>当前</th><th>新策略</th></tr></thead><tbody>${rows}</tbody></table><small>未变化的参数已隐藏，避免把版本升级误当成策略优化。</small>`}
